WITH valid AS (SELECT *, CAST(amount AS INT) AS amount_int, COALESCE(merchant, 'OTHER') AS merchant_filled FROM transactions WHERE txn_time > DATE '2023-11-08' AND txn_type IN ('FEE', 'DEBIT')), with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM valid), gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM with_prev), islands AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT merchant, DATE_TRUNC('YEAR', txn_time) AS year_start, COUNT(*) FILTER (WHERE txn_type = 'REFUND') AS refund_rows, MAX(txn_time) AS ended_at, COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) AS refund_count, MIN(txn_time) AS first_txn_time, RANK() OVER (PARTITION BY merchant ORDER BY COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) DESC) AS refund_count_rank FROM islands GROUP BY merchant, DATE_TRUNC('YEAR', txn_time) HAVING COUNT(*) FILTER (WHERE txn_type = 'REFUND') > 1 ORDER BY year_start DESC NULLS LAST;
